declarations:
declare const AUDIT_OUTCOMES: readonly [
    "succeeded",
    "denied",
    "failed"
];

type Actor = {
    readonly kind: 'user';
    readonly userId: Id;
    readonly via?: AiClient;
} | {
    readonly kind: 'service_account';
    readonly serviceAccountId: Id;
} | {
    readonly kind: 'operator';
    readonly operatorId: Id;
    readonly supportSessionId: Id;
} | {
    readonly kind: 'system';
    readonly process: string;
} | {
    readonly kind: 'anonymous';
};

interface AiClient {
    readonly kind: 'ai_client';
    readonly clientId: AiClientId;
    readonly scopes: readonly AiClientScope[];
}

type AiClientId = string & {
    readonly [aiClientIdBrand]: true;
};

interface Allow {
    readonly allow: true;
}

interface AppError<C extends string = string> {
    readonly code: C;
    readonly status: ErrorStatus;
    readonly message: string;
    readonly retryable: boolean;
    readonly fields: readonly FieldError[];
    readonly retryAfterSeconds?: number;
    readonly currentVersion?: number | string;
    readonly detail?: string;
    readonly cause?: unknown;
}

interface AppErrorOptions {
    readonly fields?: readonly FieldError[];
    readonly retryAfterSeconds?: number;
    readonly currentVersion?: number | string;
    readonly detail?: string;
    readonly cause?: unknown;
}

interface AuditEntry {
    readonly action: string;
    readonly outcome: AuditOutcome;
    readonly target?: ResourceRef;
}

interface AuditRecord {
    readonly id: Id;
    readonly tenantId: TenantId;
    readonly actor: Actor;
    readonly initiatedBy?: Actor;
    readonly correlationId: CorrelationId;
    readonly causationId?: Id;
    readonly occurredAtMillis: number;
    readonly action: string;
    readonly outcome: AuditOutcome;
    readonly target?: ResourceRef;
}

interface AuditSink {
    append(context: TenantContext, entry: AuditEntry): Promise<Result<AuditRecord, AppError>>;
}

interface AuthorizationRequest {
    readonly permission: string;
    readonly resource?: ResourceRef;
}

interface Authorizer {
    check(context: TenantContext, request: AuthorizationRequest): Promise<Decision<AuthorizationDenial>>;
}

declare const CORE_ERRORS: Readonly<{
    readonly VALIDATION_FAILED: {
