        readonly retryable: false;
    };
    readonly TENANT_REQUIRED: {
        readonly status: 403;
        readonly message: "You do not have access to this workspace.";
        readonly retryable: false;
    };
    readonly ENTITLEMENT_REQUIRED: {
        readonly status: 403;
        readonly message: "Your plan does not include this.";
        readonly retryable: false;
    };
    readonly NOT_FOUND: {
        readonly status: 404;
