        readonly status: 503;
        readonly message: "A service we depend on is not responding. Try again shortly.";
        readonly retryable: true;
    };
}>;

interface ClassificationLookup {
    classify(context: Context, field: FieldRef): Classification;
}

interface Clock {
    nowMillis(): number;
    monotonicMillis(): number;
}

interface Context {
    readonly tenantId?: TenantId;
    readonly actor: Actor;
    readonly initiatedBy?: Actor;
    readonly correlationId: CorrelationId;
    readonly causationId?: Id;
    readonly clock: Clock;
}

interface ContextInput {
    readonly tenantId?: TenantId;
    readonly actor: Actor;
    readonly initiatedBy?: Actor;
    readonly correlationId: CorrelationId;
    readonly causationId?: Id;
    readonly clock: Clock;
}

type CorrelationId = string & {
    readonly [correlationIdBrand]: true;
};

interface Deny<R extends string> {
    readonly allow: false;
    readonly reason: R;
}

interface DenyOnError {
    readonly allow: false;
    readonly reason: 'ERROR';
    readonly cause: unknown;
}

declare const ENTITLEMENT_DENIALS: readonly [
    "UNKNOWN_KEY",
    "NOT_ENTITLED"
];

interface EntitlementGate {
    check(context: TenantContext, key: string): Promise<Decision<EntitlementDenial>>;
}

interface EraserHandler {
    readonly id: string;
    erase(context: TenantContext, subject: ErasureSubject): Promise<Result<ErasureResult, AppError>>;
}

interface EraserRegistry {
    register(handler: EraserHandler): Result<void, AppError<'CONFLICT' | 'VALIDATION_FAILED'>>;
    erase(context: TenantContext, subject: ErasureSubject): Promise<ErasureReport>;
}

type ErasureOutcome = {
    readonly handlerId: string;
    readonly status: 'erased';
} | {
    readonly handlerId: string;
    readonly status: 'retained';
    readonly basis: string;
} | {
    readonly handlerId: string;
    readonly status: 'failed';
    readonly error: AppError;
};

interface ErasureReport {
    readonly complete: boolean;
    readonly outcomes: readonly ErasureOutcome[];
}

type ErasureResult = {
    readonly status: 'erased';
} | {
    readonly status: 'retained';
    readonly basis: string;
};

interface ErasureSubject {
    readonly subjectId: Id;
}

interface Err<E> {
    readonly ok: false;
    readonly error: E;
}

interface ErrorDefinition {
    readonly status: ErrorStatus;
    readonly message: string;
    readonly retryable: boolean;
}

interface ErrorResponseBody {
    readonly error: {
        readonly code: string;
        readonly message: string;
        readonly fields: readonly FieldError[];
        readonly correlation_id: CorrelationId;
        readonly retry_after_seconds?: number;
        readonly current_version?: number | string;
    };
}

interface EventEnvelope {
    readonly id: Id;
    readonly name: string;
    readonly version: number;
    readonly tenantId: TenantId;
    readonly actor: Actor;
    readonly initiatedBy?: Actor;
    readonly correlationId: CorrelationId;
    readonly causationId?: Id;
    readonly occurredAtMillis: number;
    readonly payload: JsonValue;
}

interface EventInput {
    readonly name: string;
    readonly version: number;
    readonly payload: unknown;
}

interface EventPublisher {
    publish(context: TenantContext, event: EventInput): Promise<Result<EventEnvelope, AppError>>;
}

interface FieldError {
    readonly path: string;
    readonly code: string;
}

interface FieldRef {
    readonly entity: string;
    readonly field: string;
}

type Id = string & {
    readonly [idBrand]: true;
};

interface IdGeneratorOptions {
    readonly clock: Clock;
    readonly randomBytes?: RandomBytes;
}

type JsonValue = null | boolean | number | string | readonly JsonValue[] | {
    readonly [key: string]: JsonValue;
};

declare const MESSAGE_CHANNELS: readonly [
    "email",
    "sms",
    "whatsapp"
];

interface MessageSender {
    send(context: TenantContext, message: OutboundMessage): Promise<Result<SentMessage, AppError>>;
}

type ModuleId = string & {
    readonly [moduleIdBrand]: true;
};

interface Ok<T> {
    readonly ok: true;
    readonly value: T;
}

interface OutboundMessage {
    readonly channel: MessageChannel;
    readonly to: string;
    readonly template: string;
    readonly purpose: string;
    readonly consentRef: string;
    readonly params?: Readonly<Record<string, string>>;
}

interface PlatformSecretsProvider {
    get(name: string): Promise<Result<Secret, SecretError>>;
}

type PreparedAuditEntry = AuditEntry & {
    readonly [preparedAuditEntryBrand]: true;
};

type PreparedEvent = {
    readonly name: string;
    readonly version: number;
    readonly payload: JsonValue;
} & {
    readonly [preparedEventBrand]: true;
};

type PreparedMessage = OutboundMessage & {
    readonly [preparedMessageBrand]: true;
};

interface QuotaGrant {
    readonly allow: true;
    readonly remaining: number;
}

interface QuotaProvider {
    consume(context: TenantContext, use: QuotaUse): Promise<QuotaDecision>;
}

interface QuotaUse {
    readonly quota: string;
    readonly amount: number;
    readonly idempotencyKey: string;
}

interface ResourceRef {
    readonly type: string;
    readonly id: Id;
}

declare class Secret {
    #private;
    constructor(value: string);
    reveal(): string;
    toString(): string;
    toJSON(): string;
}

interface SentMessage {
    readonly id: Id;
    readonly tenantId: TenantId;
    readonly correlationId: CorrelationId;
    readonly channel: MessageChannel;
    readonly recipient: string;
    readonly template: string;
    readonly purpose: string;
    readonly consentRef: string;
}

type TenantContext = Context & {
    readonly tenantId: TenantId;
    readonly [tenantContextBrand]: true;
};

type TenantId = Id & {
    readonly [tenantIdBrand]: true;
};

interface TenantSecretsProvider {
    get(context: TenantContext, name: string): Promise<Result<Secret, SecretError>>;
}

